:root {
  --bg-panel: #0d0d1a;
  --bg-header: #12122a;
  --bg-card: #1a1a35;
  --bg-card-alt: #1e1e40;
  --bg-track: #0a0a18;
  --color-neon-purple: #b44fff;
  --color-neon-cyan: #00e5ff;
  --color-neon-yellow: #ffe600;
  --color-neon-pink: #ff3fa4;
  --color-neon-green: #39ff8a;
  --color-warn: #ff9800;
  --color-text-primary: #e8e8ff;
  --color-text-muted: #7878aa;
  --color-border: #2a2a55;
  --color-btn-reset: #2a1040;
  --color-btn-audit: #0a2a3a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.operator-panel {
  background: var(--bg-panel);
  border: 2px solid var(--color-neon-purple);
  border-radius: 12px;
  width: 480px;
  overflow: hidden;
}

.panel-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-bottom: 2px solid var(--color-border);
}

.panel-icon {
  font-size: 20px;
  line-height: 1;
}

.panel-title-group {
  flex: 1;
}

.panel-title {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 3px;
  color: var(--color-neon-cyan);
  line-height: 1.1;
}

.panel-subtitle {
  font-size: 10px;
  color: var(--color-text-muted);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.panel-badge {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--bg-panel);
  background: var(--color-neon-green);
  padding: 2px 8px;
  border-radius: 20px;
}

.panel-body {
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat-card {
  background: var(--bg-card);
  border-radius: 8px;
  border: 1px solid var(--color-border);
  padding: 7px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-plays .stat-value {
  color: var(--color-neon-cyan);
}

.stat-revenue .stat-value {
  color: var(--color-neon-yellow);
}

.stat-high .stat-value {
  color: var(--color-neon-pink);
}

.stat-value {
  font-size: 18px;
  font-weight: 800;
  line-height: 1;
}

.stat-label {
  font-size: 10px;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.controls-row {
  display: flex;
  gap: 12px;
}

.control-group {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.control-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--color-text-muted);
}

.slider-track {
  height: 7px;
  background: var(--bg-track);
  border-radius: 4px;
  border: 1px solid var(--color-border);
  overflow: hidden;
}

.slider-fill {
  height: 100%;
  border-radius: 4px;
}

.speed-fill {
  width: 72%;
  background: var(--color-neon-purple);
}

.tilt-fill {
  width: 45%;
  background: var(--color-neon-cyan);
}

.vol-fill {
  width: 88%;
  background: var(--color-neon-yellow);
}

.control-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-text-primary);
  text-align: right;
}

.status-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-card-alt);
  border-radius: 8px;
  border: 1px solid var(--color-border);
  padding: 8px 10px;
}

.status-list {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  list-style: none;
}

.status-item {
  display: flex;
  align-items: center;
  gap: 5px;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.status-ok .status-dot {
  background: var(--color-neon-green);
}

.status-warn .status-dot {
  background: var(--color-warn);
}

.status-text {
  font-size: 11px;
  color: var(--color-text-primary);
}

.action-buttons {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.btn {
  border: none;
  border-radius: 5px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  padding: 5px 10px;
  cursor: pointer;
}

.btn-reset {
  background: var(--color-btn-reset);
  color: var(--color-neon-pink);
  border: 1px solid var(--color-neon-pink);
}

.btn-audit {
  background: var(--color-btn-audit);
  color: var(--color-neon-cyan);
  border: 1px solid var(--color-neon-cyan);
}

.panel-footer {
  background: var(--bg-header);
  border-top: 1px solid var(--color-border);
  padding: 6px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.footer-id {
  font-size: 10px;
  font-weight: 700;
  color: var(--color-neon-purple);
  letter-spacing: 1px;
  flex: 1;
}

.footer-loc {
  font-size: 10px;
  color: var(--color-text-muted);
}

.footer-time {
  font-size: 10px;
  color: var(--color-text-muted);
}
